sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 colorA;
layout(color) uniform half4 colorB;
uniform float alphaA;
uniform float alphaB;
uniform float mode;
uniform float angle;
uniform float2 center;
uniform float gradScale;
uniform float shift;
uniform float dither;
uniform float blend;
uniform float amount;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 uv = coord / size;
    float2 d = (uv - center) * float2(size.x / size.y, 1.0);
    float t = dot(uv - float2(0.5), float2(cos(radians(angle)), sin(radians(angle)))) + 0.5;
    if (mode > 0.5 && mode < 1.5) t = length(d) * 1.4142;
    else if (mode > 1.5 && mode < 2.5) t = atan(d.y, d.x) / 6.2831853 + 0.5;
    else if (mode > 2.5) t = 1.0 - abs(2.0 * t - 1.0);
    t = saturate((t - 0.5) / gradScale + 0.5 + shift);
    t += (hash21(coord) - 0.5) * dither * 0.02;
    float3 layer = mix(float3(colorA.rgb), float3(colorB.rgb), saturate(t));
    float la = mix(alphaA, alphaB, saturate(t)) * amount;
    float3 o = mix(s, blendm(s, layer, blend), la);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), 1.0);
}
